{"implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    for round_num in range(max_rounds):
        changed_in_round = False
        for p in passes:
            old = p['old']
            new = p['new']
            if old in text:
                idx = text.find(old)
                text = text[:idx] + new + text[idx+len(old):]
                applications.append(p['name'])
                changed_in_round = True
        if not changed_in_round:
            return {'applications': applications, 'fixed_point': True, 'text': text}
    return {'applications': applications, 'fixed_point': False, 'text': text}"}
